function addXP(u,a){u.xp+=a;while(u.xp>=u.xpNeeded){u.xp-=u.xpNeeded;u.level++;u.xpNeeded+=100;}}
function boostOn(u,k){return u.boosts&&u.boosts[k]&&Date.now()<u.boosts[k];}
function coinMult(u){return boostOn(u,'coin')?2:1;}
function xpMult(u){return boostOn(u,'xp')?2:1;}
function luckBonus(u){return boostOn(u,'luck')?10:0;}
function cdLeft(last,ms){var r=ms-(Date.now()-(last||0));return r>0?r:0;}
function parseBet(u,raw){var n=parseInt(raw);if(isNaN(n))n=100;if(n<10)return{err:'Min bet 10'};if(n>5000)return{err:'Max bet 5000'};if(n>u.coins)return{err:'Not enough coins'};return{amt:n};}
function addCoins(u,a){u.coins+=Math.floor(a*coinMult(u));}
