function unlockedTitles(u){return TITLES.filter(function(t){return t.check(u);}).map(function(t){return t.id;});}
function syncTitles(u){var un=unlockedTitles(u);un.forEach(function(id){if(u.titles.indexOf(id)===-1)u.titles.push(id);});return un;}
function titleName(id){var t=TITLES.find(function(x){return x.id===id;});return t?t.name:id;}
function fmt(ms){if(ms<0)ms=0;var s=Math.floor(ms/1000);return Math.floor(s/3600)+'h '+Math.floor((s%3600)/60)+'m '+(s%60)+'s';}
